import * as THREE from 'three';

import { Solution } from '../';
import { ThreeCore } from '../ThreeCore';
import { AppCommon } from './AppCommon';
import { SceneWrapper } from './SceneWrapper';
import { ActiveCommand } from './ActiveCommand';

import { CLICK_TYPE } from '../Utils/const';

export class AppCore {
	public solution: Solution;
	public threeCore: ThreeCore;
	public scene: THREE.Scene;

	public sceneWrapper: SceneWrapper;
	public common: AppCommon;
	public activeCommand: ActiveCommand;

	public navigationScene = true;
	public isPerformanceMode = true;

	constructor(solution: Solution, isPerformanceMode = false, navigationScene = false) {
		this.solution = solution;
		this.threeCore = solution.threeCore;
		this.scene = solution.threeCore.scene;

		this.isPerformanceMode = isPerformanceMode;
		this.navigationScene = navigationScene;

		this.common = new AppCommon(this);
		this.activeCommand = new ActiveCommand(this);
		this.solution.threeCore.readyBinding = () => {
			return this.ready;
		};
		this.sceneWrapper = new SceneWrapper(this);
		this.sceneWrapper.activateGlobe = this.navigationScene;
	}
	public initPost() {
		this.sceneWrapper.initPost();
	}
	public get ready() {
		return this.sceneWrapper.ready;
	}
	public update(): boolean {
		return this.sceneWrapper.update();
	}
	public onMouseEventListener(e: MouseEvent, type: CLICK_TYPE) {
		this.activeCommand.onMouseEventListener(e, type);
	}

	public destroy() {}
}
