export const showGraphDrone = (divUI: HTMLDivElement) => {
	const wrapper = document.createElement('div');
	wrapper.style.position = 'relative';
	wrapper.style.width = '300px';
	wrapper.style.height = '300px';
	wrapper.style.background = '#ccc';
	wrapper.style.border = '1px solid #999';
	wrapper.style.borderRadius = '6px';
	wrapper.style.overflow = 'hidden';
	divUI.appendChild(wrapper);

	const canvas = document.createElement('canvas');
	canvas.width = 300;
	canvas.height = 300;
	wrapper.appendChild(canvas);

	const btn = document.createElement('button');
	btn.textContent = 'Close ✕';
	btn.style.position = 'absolute';
	btn.style.top = '8px';
	btn.style.left = '8px';
	btn.style.zIndex = '10';
	btn.style.padding = '4px 8px';
	btn.style.background = 'rgba(0,0,0,0.5)';
	btn.style.color = 'white';
	btn.style.border = 'none';
	btn.style.borderRadius = '4px';
	btn.style.cursor = 'pointer';
	wrapper.appendChild(btn);

	const ctx = canvas.getContext('2d');
	if (!ctx) return;

	const maxPoints = 50;
	const padding = 30;
	const width = canvas.width - padding * 2;
	const height = canvas.height - padding * 2;

	let base = 50;
	const spikeThreshold = 90;
	const data: { time: number; value: number; spike: boolean }[] = [];

	const updateChart = () => {
		const now = Date.now();

		let value = base + Math.sin(data.length / 5) * 10 + Math.random() * 5;

		if (Math.random() < 0.05) {
			value += 50 + Math.random() * 30;
		}

		const spike = value > spikeThreshold;
		data.push({ time: now, value, spike });
		if (data.length > maxPoints) data.shift();

		const minTime = data[0].time;
		const maxTime = data[data.length - 1].time;
		const minValue = Math.min(...data.map((d) => d.value));
		const maxValue = Math.max(...data.map((d) => d.value));

		ctx.fillStyle = '#ccc';
		ctx.fillRect(0, 0, canvas.width, canvas.height);

		ctx.strokeStyle = '#555';
		ctx.lineWidth = 1;
		ctx.beginPath();
		ctx.moveTo(padding, padding);
		ctx.lineTo(padding, canvas.height - padding);
		ctx.lineTo(canvas.width - padding, canvas.height - padding);
		ctx.stroke();

		data.forEach((point) => {
			if (point.spike) {
				const x = padding + ((point.time - minTime) / (maxTime - minTime)) * width;
				ctx.fillStyle = 'rgba(255, 255, 0, 0.2)';
				ctx.fillRect(x - 5, padding, 10, height);
			}
		});

		ctx.strokeStyle = '#0077cc';
		ctx.lineWidth = 2;
		ctx.beginPath();
		data.forEach((point, i) => {
			const x = padding + ((point.time - minTime) / (maxTime - minTime)) * width;
			const y = canvas.height - padding - ((point.value - minValue) / (maxValue - minValue)) * height;
			if (i === 0) ctx.moveTo(x, y);
			else ctx.lineTo(x, y);
		});
		ctx.stroke();

		data.forEach((point) => {
			const x = padding + ((point.time - minTime) / (maxTime - minTime)) * width;
			const y = canvas.height - padding - ((point.value - minValue) / (maxValue - minValue)) * height;
			ctx.beginPath();
			ctx.arc(x, y, 3, 0, Math.PI * 2);
			ctx.fillStyle = point.spike ? 'yellow' : 'red';
			ctx.fill();
		});

		ctx.fillStyle = '#000';
		ctx.font = '10px sans-serif';
		ctx.fillText(`${Math.round(maxValue)}%`, 4, padding);
		ctx.fillText(`${Math.round(minValue)}%`, 4, canvas.height - padding + 10);
		ctx.fillText('Now', canvas.width - padding - 20, canvas.height - padding + 12);
	};

	const intervalId = setInterval(updateChart, 100);

	btn.addEventListener('click', () => {
		clearInterval(intervalId);
		wrapper.remove();
	});
};

export const showGraph = (divUI: HTMLDivElement) => {
	const wrapper = document.createElement('div');
	wrapper.style.position = 'relative';
	wrapper.style.width = '300px';
	wrapper.style.height = '300px';
	wrapper.style.marginTop = '5px';
	wrapper.style.background = '#ccc';
	wrapper.style.border = '1px solid #999';
	wrapper.style.borderRadius = '6px';
	wrapper.style.overflow = 'hidden';
	divUI.appendChild(wrapper);

	const canvas = document.createElement('canvas');
	canvas.width = 300;
	canvas.height = 300;
	wrapper.appendChild(canvas);

	const btn = document.createElement('button');
	btn.textContent = 'Close ✕';
	btn.style.position = 'absolute';
	btn.style.top = '8px';
	btn.style.left = '8px';
	btn.style.zIndex = '10';
	btn.style.padding = '4px 8px';
	btn.style.background = 'rgba(0,0,0,0.5)';
	btn.style.color = 'white';
	btn.style.border = 'none';
	btn.style.borderRadius = '4px';
	btn.style.cursor = 'pointer';
	wrapper.appendChild(btn);

	const ctx = canvas.getContext('2d');
	if (!ctx) return;

	const maxPoints = 50;
	const padding = 30;
	const width = canvas.width - padding * 2;
	const height = canvas.height - padding * 2;

	let base = 50;
	const data: { time: number; value: number }[] = [];

	const updateChart = () => {
		const now = Date.now();
		const next = base + Math.sin(data.length / 5) * 10 + Math.random() * 10;
		data.push({ time: now, value: next });

		if (data.length > maxPoints) data.shift();

		const minTime = data[0].time;
		const maxTime = data[data.length - 1].time;
		const minValue = Math.min(...data.map((d) => d.value));
		const maxValue = Math.max(...data.map((d) => d.value));

		ctx.fillStyle = '#ccc';
		ctx.fillRect(0, 0, canvas.width, canvas.height);

		ctx.strokeStyle = '#555';
		ctx.lineWidth = 1;
		ctx.beginPath();
		ctx.moveTo(padding, padding);
		ctx.lineTo(padding, canvas.height - padding);
		ctx.lineTo(canvas.width - padding, canvas.height - padding);
		ctx.stroke();

		ctx.strokeStyle = '#0077cc';
		ctx.lineWidth = 2;
		ctx.beginPath();
		data.forEach((point, i) => {
			const x = padding + ((point.time - minTime) / (maxTime - minTime)) * width;
			const y = canvas.height - padding - ((point.value - minValue) / (maxValue - minValue)) * height;
			if (i === 0) ctx.moveTo(x, y);
			else ctx.lineTo(x, y);
		});
		ctx.stroke();

		ctx.fillStyle = '#cc0000';
		data.forEach((point) => {
			const x = padding + ((point.time - minTime) / (maxTime - minTime)) * width;
			const y = canvas.height - padding - ((point.value - minValue) / (maxValue - minValue)) * height;
			ctx.beginPath();
			ctx.arc(x, y, 2, 0, Math.PI * 2);
			ctx.fill();
		});

		ctx.fillStyle = '#000';
		ctx.font = '10px sans-serif';
		ctx.fillText(`${Math.round(maxValue)}%`, 4, padding);
		ctx.fillText(`${Math.round(minValue)}%`, 4, canvas.height - padding + 10);
		ctx.fillText('Now', canvas.width - padding - 20, canvas.height - padding + 12);
	};

	const intervalId = setInterval(updateChart, 100);

	btn.addEventListener('click', () => {
		clearInterval(intervalId);
		wrapper.remove();
	});
};

export const showCamera = async (divUI: HTMLDivElement) => {
	// console.log("appendCamera");

	const wrapper = document.createElement('div');
	wrapper.style.position = 'relative';
	wrapper.style.width = '300px';
	wrapper.style.height = '230px';
	wrapper.style.marginTop = '5px';
	divUI.appendChild(wrapper);

	const video = document.createElement('video');
	video.autoplay = true;
	video.muted = true;
	video.playsInline = true;
	video.style.width = '100%';
	video.style.height = '100%';
	wrapper.appendChild(video);

	const btn = document.createElement('button');
	btn.textContent = 'Close ✕';
	btn.style.position = 'absolute';
	btn.style.top = '8px';
	btn.style.left = '8px';
	btn.style.zIndex = '10';
	btn.style.padding = '4px 8px';
	btn.style.background = 'rgba(0,0,0,0.5)';
	btn.style.color = 'white';
	btn.style.border = 'none';
	btn.style.borderRadius = '4px';
	btn.style.cursor = 'pointer';
	wrapper.appendChild(btn);

	btn.addEventListener('click', () => {
		const stream = video.srcObject as MediaStream;
		if (stream) {
			stream.getTracks().forEach((track) => track.stop());
		}
		wrapper.remove();
	});

	try {
		const stream = await navigator.mediaDevices.getUserMedia({
			video: true,
			audio: false,
		});
		video.srcObject = stream;
	} catch (err) {
		console.error('error:', err);
	}
};
